    void handleBackPressed(){if(store==null){finish();return;}if(editing&&"termsOnboarding".equals(draftTable)){Onboarding.show(this,draft,setupStep);return;}if(editing&&"onboarding".equals(draftTable)){if(setupStep>0)Onboarding.show(this,draft,setupStep-1);else welcome();return;}if(editing){confirm("Discard changes?","Your saved record will stay unchanged.",()->{if("media".equals(draftTable))MediaLibrary.discardDraft(this,draft);editing=false;draft=null;if(editorReturn!=null)editorReturn.run();else home();});return;}if(!back.isEmpty())back.pop().run();else if(!route.equals("Today"))home();else {backCallback.setEnabled(false);getOnBackPressedDispatcher().onBackPressed();backCallback.setEnabled(true);}}
    void announce(String message){
        if(feedback==null||message==null||message.trim().isEmpty())return;
        TextView target=feedback;target.setVisibility(View.VISIBLE);
        if(message.contentEquals(target.getText())){target.setText("");target.post(()->{if(target==feedback&&target.isAttachedToWindow())target.setText(message);});}
        else target.setText(message);
    }
    void speak(String message){AccessibilityManager a=getSystemService(AccessibilityManager.class);if(a.isTouchExplorationEnabled())announce(message);else if(speechReady)tts.speak(message,TextToSpeech.QUEUE_FLUSH,null,"score");}
    void error(String message){new AlertDialog.Builder(this).setTitle("Please check").setMessage(message).setPositiveButton("OK",null).show();}
    void confirm(String title,String message,Runnable yes){new AlertDialog.Builder(this).setTitle(title).setMessage(message).setNegativeButton("Cancel",null).setPositiveButton("Confirm",(d,w)->yes.run()).show();}
    void refreshReminders(){try{ReminderReceiver.schedule(this,store);}catch(RuntimeException e){announce("Record saved. Reminders could not be updated; check Android notification settings.");}}
    boolean save(){try{store.save();refreshReminders();return true;}catch(Exception e){error("Could not save: "+e.getMessage());return false;}}
    boolean milestoneFeedback;
    boolean saveRecord(String table,JSONObject r){milestoneFeedback=false;java.util.Set<String> before=java.util.Collections.emptySet();boolean consider=object(store.settings(),"sounds").optBoolean("milestonesEnabled",true)&&(table.equals("tournaments")||table.equals("matches")&&status(table,r).equals("Completed")||table.equals("trainingSessions")&&status(table,r).equals("Completed"));try{if(consider)before=Achievements.earned(this);store.saveRecord(table,r);refreshReminders();}catch(Exception e){error("Could not save: "+e.getMessage());return false;}if(consider)try{java.util.Set<String> after=Achievements.earned(this);after.removeAll(before);if(!after.isEmpty()){sound("milestonesEnabled","tennis_applause");milestoneFeedback=true;}}catch(Exception ignored){/* Optional feedback cannot invalidate an already committed record. */}return true;}

    List<JSONObject> mine(String table){List<JSONObject> list=new ArrayList<>();JSONObject p=store.player();for(JSONObject r:rows(store.table(table)))if(p==null||CoachInsights.includes(r,p.optString("id"))&&r.optString("sport","Tennis").equals(ProfileSetup.sport(p)))list.add(r);list.sort(Comparator.comparingLong(r->millis(r,"date")));return list;}
