    EditText field(JSONObject target,String key,String label,boolean numeric){TextView caption=text(label,15,true);EditText e=new EditText(this);e.setId(View.generateViewId());boundFields.computeIfAbsent(target,k->new HashMap<>()).put(key,e);caption.setLabelFor(e.getId());body.addView(caption);e.setText(target.optString(key,""));e.setTextSize(17);e.setTextColor(ink);e.setHintTextColor(muted);e.setMinHeight(dp(52));e.setMinimumHeight(dp(52));e.setBackgroundTintList(ColorStateList.valueOf(green));e.setInputType(numeric?android.text.InputType.TYPE_CLASS_NUMBER:android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_CAP_SENTENCES|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE);e.setMaxLines(numeric?1:5);body.addView(e,lp());e.addTextChangedListener(watcher(s->{if(numeric){try{put(target,key,Integer.parseInt(s));}catch(NumberFormatException ex){if(s.trim().isEmpty())target.remove(key);else put(target,key,-1);}}else put(target,key,s);}));return e;}
